/**
 * Guard: what app.json asks of the Android release build (REGISTRE V-22, pass 81).
 *
 * android/ is gitignored and regenerated by prebuild on every EAS build, so the
 * native release configuration exists only as the plugin options in app.json.
 * Before this file, nothing read them: release builds shipped with R8 off
 * (minifyEnabled resolved false, Play Console "Obfuscation 1%"), and turning it
 * on alone would have broken two things nobody would have seen in a test run.
 *
 * - expo-notifications persists every scheduled request with Java
 *   serialization, so the stored bytes carry its class names. Its own keep rule
 *   is never applied (the prebuilt AAR ships no proguard.txt), and an
 *   obfuscated rename makes the stored daily reminder unreadable after an
 *   update. The keep rule has to come from the app.
 * - An obfuscated build without its R8 mapping turns every native stack trace
 *   in Sentry into renamed frames. The mapping is uploaded at build time by the
 *   Sentry Android Gradle plugin, which the Expo plugin applies only when asked.
 *
 * Owner decision 1 (pass 81): minify on, no resource shrinking, the keep rule,
 * and the Gradle plugin on with native sources NOT uploaded.
 *
 * The status bar plugin registration is checked here too, since it is also a
 * line of app.json: see plugins/withoutStatusBarColor.js for why it exists.
 *
 * Nothing here prints an option value it does not have to. The Sentry project
 * settings are checked by type and length, and a stray auth token is looked for
 * by key, so a failure can never echo one.
 */

import * as fs from 'fs';
import * as path from 'path';
import { validateConfig } from 'expo-build-properties/build/pluginConfig';

const REPO_ROOT = path.resolve(__dirname, '..', '..');

type PluginEntry = string | [string, Record<string, unknown>];

/** The keep rule expo-notifications ships but never applies, verbatim. */
const NOTIFICATIONS_KEEP_RULE = '-keep class expo.modules.notifications.** { *; }';

const STATUS_BAR_PLUGIN = './plugins/withoutStatusBarColor';
const SPLASH_PLUGIN = 'expo-splash-screen';

function plugins(): PluginEntry[] {
    const appJson = JSON.parse(fs.readFileSync(path.join(REPO_ROOT, 'app.json'), 'utf8'));
    return appJson.expo.plugins;
}

function pluginName(entry: PluginEntry): string {
    return typeof entry === 'string' ? entry : entry[0];
}

/** The options object of a plugin entry, or an empty object if it has none. */
function pluginOptions(name: string): Record<string, any> {
    const entry = plugins().find((candidate) => pluginName(candidate) === name);
    return entry !== undefined && typeof entry !== 'string' ? entry[1] : {};
}

const buildProperties = () => pluginOptions('expo-build-properties');
const sentry = () => pluginOptions('@sentry/react-native/expo');

describe('Android release build config (V-22)', () => {
    it('enables R8 minification in release builds', () => {
        expect(buildProperties().android?.enableMinifyInReleaseBuilds).toBe(true);
    });

    it('carries the expo-notifications keep rule', () => {
        const rules: string = buildProperties().android?.extraProguardRules ?? '';
        const lines = rules.split('\n').map((line) => line.trim());

        expect(lines).toContain(NOTIFICATIONS_KEEP_RULE);
    });

    it('applies the Sentry Android Gradle plugin, which uploads the R8 mapping', () => {
        expect(sentry().experimental_android?.enableAndroidGradlePlugin).toBe(true);
    });

    it('does not upload native sources to Sentry', () => {
        // Explicitly false, not merely absent: the Expo plugin defaults it to true
        // once the Gradle plugin is on.
        expect(sentry().experimental_android?.includeNativeSources).toBe(false);
    });

    // CONTROL, not a regression test: true before and after this change. It
    // holds the "no resource shrinking" half of the decision in place - the
    // shrinker can drop images React Native looks up by name at run time.
    it('does not enable resource shrinking', () => {
        expect(buildProperties().android?.enableShrinkResourcesInReleaseBuilds).not.toBe(true);
    });

    // CONTROL: the options must stay something the package itself accepts. It
    // throws, for example, on resource shrinking without minification.
    it('passes the expo-build-properties schema', () => {
        const options = JSON.parse(JSON.stringify(buildProperties()));
        expect(() => validateConfig(options)).not.toThrow();
    });

    // CONTROL: the existing Sentry project settings survive the change, and no
    // auth token is ever committed here (the build reads SENTRY_AUTH_TOKEN).
    it('keeps the Sentry project settings and carries no auth token', () => {
        const options = sentry();
        for (const key of ['url', 'organization', 'project']) {
            expect(typeof options[key]).toBe('string');
            expect((options[key] as string).length).toBeGreaterThan(0);
        }
        expect(Object.keys(options)).not.toContain('authToken');
    });
});

describe('status bar plugin registration', () => {
    it('registers withoutStatusBarColor after the splash screen plugin', () => {
        const names = plugins().map(pluginName);
        const splash = names.indexOf(SPLASH_PLUGIN);

        expect(splash).toBeGreaterThanOrEqual(0);
        expect(names.indexOf(STATUS_BAR_PLUGIN)).toBeGreaterThan(splash);
    });
});
